import {renderMarkdown,renderInline} from './markdown.js';
import topics,{categories,metadata} from './data/topics.js';
import briefs from './data/briefs.js';
import {imageGalleryHTML} from './image-gallery.js';
import {insertSectionVisuals} from './educational-visuals.js';
import {topicImages} from './data/illustrations.js';
import {routeHash,sectionKey,sectionElementId} from './guide-links.js';

const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shareButton=(key,label='이 부분 공유')=>`<button type="button" class="section-share" data-share-scope="${key}" aria-label="${escape(label)}">공유 · QR ↗</button>`;
const landing=(t,key,selected)=>selected===key?`<div class="shared-landing"><p>${escape(t.title)} · 공유받은 설명</p><div><a href="${routeHash(t.id)}">전체 설명</a><a href="${routeHash(t.id,{view:'brief'})}">1분 요약</a></div></div>`:'';
const sectionHTML=(s,t,i,selected)=>{
  const key=sectionKey(s);
  const cls=({content:'article-section',symptoms:'symptom-section',urgent:'article-urgent',care:'care-box',faq:'faq',sources:'sources'})[s.role]||'article-section';
  const body=insertSectionVisuals(s.role==='faq'&&t.faq.length?t.faq.map(f=>`<details><summary>${renderInline(f.q)}</summary><div class="faq-answer">${renderMarkdown(f.answerMarkdown,f.q)}</div></details>`).join(''):renderMarkdown(s.markdown,s.title),t.id);
  return `<section class="guide-section ${cls} ${selected===key?'shared-section':''}" id="${sectionElementId(key)}" tabindex="-1">${landing(t,key,selected)}<div class="section-heading-row"><h2>${s.role==='content'?`<span class="section-no">${String(i+1).padStart(2,'0')}</span>`:''}${escape(s.title)}</h2>${shareButton(key,`${s.title} 공유`)}</div><div class="markdown-body ${s.role==='symptoms'?'symptoms-content':''}">${body}</div>${imageGalleryHTML(t.id,s.title)}${s.role==='sources'?`<p class="source-date">제공된 원고 반영 · 문구 갱신 ${metadata.updated}<br>개인별 진료 결과와 국내 허가·사용 가능 여부에 따라 치료 계획은 달라질 수 있습니다.</p>`:''}</section>`;
};
export function navigationHTML(currentId,groupIcon){
  const current=topics.find(t=>t.id===currentId);
  return categories.slice(1).map(c=>`<details class="nav-group" ${current?.category===c.id||(!currentId&&c.id==='anterior')?'open':''}><summary><span class="nav-symbol">${groupIcon(c.id)}</span>${c.label}<span class="nav-count">${topics.filter(t=>t.category===c.id).length}</span></summary><div class="nav-items">${topics.filter(t=>t.category===c.id).map(t=>`<a href="#/${t.id}" class="nav-item ${t.number.split('.').length>2?'is-child':''} ${currentId===t.id?'active':''}" ${currentId===t.id?'aria-current="page"':''} title="${escape(t.title)}"><span class="nav-number">${t.number}</span>${escape(t.shortTitle)}</a>`).join('')}</div></details>`).join('');
}
function briefHTML(t){
  const brief=briefs[t.id];
  return `<section class="clinic-brief" id="clinic-brief" aria-label="진료실 1분 요약"><div class="brief-intro"><span>함께 보는 1분 안내</span><p>그림과 세 가지 핵심으로 먼저 살펴보세요.</p></div><div class="brief-layout"><figure class="brief-picture"><img src="./images/cards/${t.id}.svg" width="640" height="360" alt="${escape(t.shortTitle)}의 특징을 단순화한 모식도"><figcaption>질환·치료의 특징을 설명하는 모식도</figcaption><a class="brief-picture-link" href="${routeHash(t.id,{section:'illustrations'})}">검사 사진·설명 그림 자세히 보기 ↗</a></figure><div class="brief-points">${[['problem','01','어떤 문제인가요?'],['care','02','어떻게 관리하나요?'],['alert','03','언제 바로 연락하나요?']].map(([key,n,title])=>`<section class="brief-point brief-${key}"><h2><span>${n}</span>${title}</h2><p>${escape(brief[key])}</p></section>`).join('')}</div></div><div class="brief-bottom"><a class="primary-button" href="${routeHash(t.id)}">자세한 설명 읽기</a><button class="secondary-button" data-share-scope="brief">이 요약 공유 · QR</button><p>검사 결과에 따라 본인의 관리 계획은 달라질 수 있습니다.</p></div></section>`;
}
export function articleHTML(t,{icon,groupIcon},route={view:'detail',section:null}){
  const category=categories.find(c=>c.id===t.category),isBrief=route.view==='brief';
  const familyNumber=t.number.split('.').slice(0,2).join('.');
  const family=topics.filter(x=>x.id!==t.id&&(x.number===familyNumber||x.number.startsWith(familyNumber+'.')));
  const related=family.length?family:topics.filter(x=>x.category===t.category&&x.id!==t.id).slice(0,6);
  const toc=(key,label)=>`<a href="${routeHash(t.id,{section:key})}" ${route.section===key?'aria-current="location"':''}>${escape(label)}</a>`;
  const details=`<div class="article-grid"><div class="article-content"><section class="key-message ${route.section==='key'?'shared-section':''}" id="key-message" tabindex="-1">${landing(t,'key',route.section)}<div class="section-heading-row"><span class="label">이것만은 기억하세요</span>${shareButton('key','핵심 안내 공유')}</div><div class="markdown-body">${renderMarkdown(t.keyMarkdown)}</div></section><div id="illustrations-target" tabindex="-1">${landing(t,'illustrations',route.section)}${imageGalleryHTML(t.id)}<div class="visual-share">${shareButton('illustrations','그림 설명 공유')}</div></div>${t.sections.map((s,i)=>sectionHTML(s,t,i,route.section)).join('')}</div><aside class="article-aside" aria-label="이 페이지 목차"><div class="aside-sticky"><p class="aside-label">IN THIS GUIDE</p><nav class="article-toc">${toc('key','핵심 안내')}${toc('illustrations',topicImages[t.id]?.tocLabel || '그림으로 이해하기')}${t.id==='floaters-pvd'?toc('vitreous-model','유리체 액화 3D'):''}${t.sections.map(s=>toc(sectionKey(s),s.title)).join('')}</nav><div class="font-controls"><span>본문 글자 크기</span><div><button id="font-smaller" aria-label="본문 글씨 작게">A−</button><button id="font-larger" aria-label="본문 글씨 크게">A+</button></div></div><p class="aside-tip">위쪽의 ‘1분 요약’으로<br>핵심을 먼저 함께 볼 수 있습니다.</p></div></aside></div>`;
  return `<article class="${isBrief?'is-brief':''}"><div class="article-actions"><a class="back-link" href="#/">${icon('back',14)} 전체 안내로</a><div class="action-buttons"><button class="secondary-button" id="print-guide">${icon('print',14)} 인쇄</button><button class="secondary-button" id="share-guide" data-share-scope="${isBrief?'brief':'all'}">${icon('share',14)} 공유 · QR</button></div></div><header class="article-heading with-illustrations"><div><span class="article-tag">${groupIcon(t.category)} ${category.label} <span class="topic-number">${t.number}</span></span><h1 class="${t.title.length>25?'long-title':''}">${escape(t.title)}</h1><p class="article-english">${escape(t.english)}</p>${isBrief?'':`<div class="article-summary markdown-body">${renderMarkdown(t.summaryMarkdown)}</div>`}</div></header><nav class="guide-modes" aria-label="설명 보기 방식"><a href="${routeHash(t.id,{view:'brief'})}" ${isBrief?'aria-current="page"':''}>1분 요약</a><a href="${routeHash(t.id)}" ${!isBrief?'aria-current="page"':''}>자세히 읽기</a></nav>${isBrief?briefHTML(t):details}${related.length&&!isBrief?`<section class="related"><h2>함께 읽어보세요</h2><div class="related-links">${related.map(x=>`<a href="#/${x.id}">${escape(x.shortTitle)} ↗</a>`).join('')}</div></section>`:''}</article>`;
}
